import java.util.*;

class Solution {
  public boolean checkSubarraySum(int[] nums, int k) {
    Map<Integer, Integer> firstIndex = new HashMap<>(); // prefix sum mod k -> earliest index
    firstIndex.put(0, -1);
    int sum = 0;
    for (int i = 0; i < nums.length; i++) {
      sum = (sum + nums[i]) % k;
      Integer prev = firstIndex.putIfAbsent(sum, i);
      if (prev != null && i - prev >= 2) return true;
    }
    return false;
  }
}
